// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address _rewardToken) public {
        vm.assume(_rewardToken != address(0));
        // Deployer is initially the owner
        address initialOwner = address(this);
        // Add a reward token to have at least one public getter involved
        // This does not affect the owner() function
        c.addReward(_rewardToken);
        // General rule: owner() must not return the zero address when the owner was set to a non-zero address
        address currentOwner = c.owner();
        assertTrue(currentOwner != address(0));
    }
}

